<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ascii-terminal</title>
<style>
  :root {
    --bg: #0c0f14;
    --fg: #aab8c9;
    --bright: #d8e2ef;
    --accent: #6ee7b7;
    --dim: #556070;
    --prompt: #e879f9;
    --panel: rgba(255,255,255,0.045);
    --line: rgba(255,255,255,0.08);
  }
  html, body { height: 100%; }
  body {
    margin: 0;
    background: var(--bg);
    color: var(--fg);
    font-family: "SFMono-Regular", "Cascadia Code", "DejaVu Sans Mono",
                 "Fira Code", Menlo, Consolas, monospace;
    font-size: 14px;
    line-height: 1.45;
  }
  #wrap { height: 100%; display: flex; flex-direction: column; box-sizing: border-box; padding: 12px; }
  #header { display: flex; justify-content: space-between; align-items: baseline; padding: 2px 4px 8px; }
  #header .title { font-weight: 700; letter-spacing: 1px; color: var(--bright); }
  #header .title span { color: var(--accent); }
  #header .hint { color: var(--dim); font-size: 12px; }
  #screen {
    flex: 1;
    overflow-y: auto;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 10px 12px;
    white-space: pre;
    scrollbar-width: thin;
  }
  #screen::-webkit-scrollbar { width: 8px; }
  #screen::-webkit-scrollbar-thumb { background: var(--line); border-radius: 4px; }
  .row { display: block; }
  .row.fade { opacity: 0.4; }
  .row.blank { height: 1.45em; }
  #inputrow { display: flex; align-items: center; padding-top: 10px; }
  #prompt { color: var(--prompt); margin-right: 8px; user-select: none; }
  #cmd {
    flex: 1;
    background: transparent;
    border: none;
    outline: none;
    color: var(--bright);
    font: inherit;
    caret-color: var(--accent);
  }
  #status { padding: 2px 4px 0; color: var(--dim); font-size: 12px; display: flex; gap: 18px; flex-wrap: wrap; }

  body.theme-amber {
    --bg: #17100a; --fg: #b89a6a; --bright: #f0d9a8; --accent: #ffb454;
    --dim: #6b5638; --prompt: #ff8f5e; --panel: rgba(255,170,80,0.05); --line: rgba(255,170,80,0.14);
  }
  body.theme-matrix {
    --bg: #041004; --fg: #4f9d63; --bright: #9df2b2; --accent: #00ff66;
    --dim: #1f6b33; --prompt: #00ff66; --panel: rgba(0,255,100,0.04); --line: rgba(0,255,100,0.14);
  }
  body.theme-paper {
    --bg: #f4f1e8; --fg: #6b6f5e; --bright: #3b3f2f; --accent: #2f6f4f;
    --dim: #a8a48f; --prompt: #b5453a; --panel: rgba(0,0,0,0.03); --line: rgba(0,0,0,0.12);
  }
</style>
</head>
<body>
<div id="wrap">
  <div id="header">
    <div class="title">~ <span>ascii-terminal</span></div>
    <div class="hint">type <b>help</b> or press <b>?</b> &mdash; Enter on empty line toggles the animation</div>
  </div>
  <div id="screen" aria-live="off"></div>
  <div id="inputrow">
    <span id="prompt">&gt;</span>
    <input id="cmd" type="text" autocomplete="off" spellcheck="false" autofocus placeholder="type a command…">
  </div>
  <div id="status">
    <span id="st-theme">theme: night</span>
    <span id="st-speed">speed: 5</span>
    <span id="st-rows">rows: 24</span>
    <span id="st-state">state: running</span>
  </div>
</div>
<script>
(() => {
  "use strict";

  const screenEl = document.getElementById("screen");
  const cmdEl = document.getElementById("cmd");
  const statusEls = {
    theme: document.getElementById("st-theme"),
    speed: document.getElementById("st-speed"),
    rows:  document.getElementById("st-rows"),
    state: document.getElementById("st-state"),
  };

  const THEMES = { night: "night", amber: "amber", matrix: "matrix", paper: "paper" };
  const state = { theme: "night", speed: 5, running: true, tick: 0, scroll: 0, rows: 24 };

  // ---------- ASCII scene generation ----------
  // Three overlapping layers with sinusoidal parallax: stars far away,
  // hills in the middle, and bushes/rocks in the foreground.

  const rand = (a, b) => a + Math.random() * (b - a);
  const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
  const mod = (n, m) => ((n % m) + m) % m;

  const STAR = " .·*+o";
  const HILL = {
    dark:  ["▓", "▒", "░"],
    light: ["█", "▓", "▒"],
  };
  const BUSHES = ["§", "♣", "⚘", "⌂", "✿", "٭"];
  const ROCKS  = ["#", "&", "%", "@"];
  const CLOUD  = "·`´-~_";

  function makeStars() {
    const stars = [];
    for (let i = 0; i < 60; i++) stars.push({ x: rand(0, 140), y: rand(0, 10), c: pick(STAR) });
    return stars;
  }
  function makeHills() {
    const hills = [];
    for (let i = 0; i < 9; i++) hills.push({ x: rand(0, 140), w: rand(8, 20), h: rand(3, 6) });
    return hills;
  }
  function makeProps() {
    const props = [];
    for (let i = 0; i < 14; i++) props.push({ x: rand(0, 140), kind: Math.random() < 0.65 ? "bush" : "rock" });
    return props;
  }

  const stars = makeStars();
  const hills = makeHills();
  const props = makeProps();

  function layerCells(offset) {
    const rows = new Map(); // y -> Map(ch -> count)
    const add = (y, ch) => {
      if (y < 0 || y > 5) return;
      let row = rows.get(y);
      if (!row) { row = new Map(); rows.set(y, row); }
      row.set(ch, (row.get(ch) || 0) + 1);
    };

    for (const s of stars) {
      const x = mod(Math.round(s.x - offset * 0.25), 140);
      add(Math.round(s.y), s.c);
    }
    for (const h of hills) {
      for (let i = 0; i < h.w; i++) {
        const x = mod(Math.round(h.x + i - offset * 0.5), 140);
        const y = 5 - Math.round(h.h * Math.sin((i / h.w) * Math.PI));
        const ch = y > 3 ? pick(HILL.dark) : pick(HILL.light);
        add(y, ch);
      }
    }
    for (const p of props) {
      const x = mod(Math.round(p.x - offset), 140);
      add(4 + (p.kind === "rock" ? 1 : 0), p.kind === "rock" ? pick(ROCKS) : pick(BUSHES));
    }
    return rows;
  }

  function renderRows() {
    const offset = state.scroll;
    const rows = [];
    for (let i = 0; i < state.rows; i++) rows.push(Array(140).fill(" "));

    // ground line
    const g = Math.floor(state.rows * 0.82);
    for (let x = 0; x < 140; x++) rows[g][x] = "─";

    const fillRow = (y, cells) => {
      const r = rows[y];
      for (const [ch, n] of cells) {
        for (let k = 0; k < n; k++) {
          const x = Math.floor(Math.random() * 140);
          if (r[x] === " ") r[x] = ch;
        }
      }
    };

    // stars and clouds in the upper band
    for (let y = 0; y < Math.min(6, g); y++) {
      const cells = layerCells(offset).get(y);
      if (cells) fillRow(y, cells);
      if (Math.random() < 0.03) {
        const x = Math.floor(Math.random() * 140);
        rows[y][x] = pick(CLOUD);
      }
    }
    // hills
    for (let y = Math.max(0, g - 6); y < g; y++) {
      const cells = layerCells(offset).get(y);
      if (cells) fillRow(y, cells);
    }
    // foreground props
    for (let y = g - 2; y < g; y++) {
      const cells = layerCells(offset).get(y);
      if (cells) fillRow(y, cells);
    }
    // a little moon, fixed in the sky
    const moonY = Math.floor(g * 0.25), moonX = 116;
    if (moonY < g) {
      rows[moonY][moonX] = "☾";
      rows[moonY][moonX + 1] = " ";
    }

    const line = rows.map((r) => r.join("")).join("'"\\n\");
    screenEl.textContent = line;
  }

  // ---------- terminal chrome ----------
  const banner = [
    \"╭───────────────────────────────────────────────╮\",
    \"│  ascii-terminal · a little scrolling landscape │\",
    \"╰───────────────────────────────────────────────╯\",
  ].join(\"\\n\");

  const helpText = [
    banner,
    \"\",
    \"commands\",
    \"  help                 show this list\",
    \"  speed <1-10>         set scroll speed\",
    \"  theme <night|amber|matrix|paper>\",
    \"                       switch color scheme\",
    \"  clear                wipe scrollback\",
    \"  about                about this thing\",
    \"  quit                 stop the animation\",
    \"\",
    \"tips: empty line toggles run/pause · '?' prints this\",
    \"\",
  ].join(\"\\n\");

  const aboutText = [
    \"ascii-terminal is a tiny zero-dependency toy:\",
    \"a few layers of sinusoidal parallax pretending to be\",
    \"a landscape, rendered as monospace text every frame.\",
    \"Built in ~2026, no frameworks were harmed.\",
    \"\",
  ].join(\"\\n\");

  // ---------- output ----------
  function appendRow(text, fade = false) {
    const div = document.createElement(\"div\");
    div.className = \"row\" + (fade ? \" fade\" : \"\");
    div.textContent = text;
    screenEl.appendChild(div);
    // cheap cap on scrollback
    while (screenEl.childElementCount > 600) screenEl.removeChild(screenEl.firstElementChild);
  }

  function push(text) {
    if ("'!text) { appendRow(""); return; }
    text.split("'"\\n\").forEach((line) => appendRow(line));
  }

  function pushInline(lines) {
    lines.forEach((line) => appendRow(line, true));
  }

  function syncStatus() {
    statusEls.theme.textContent = "'`theme: ${state.theme}`;
    statusEls.speed.textContent = `speed: ${state.speed}`;
    statusEls.rows.textContent  = `rows: ${state.rows}`;
    statusEls.state.textContent = `state: ${state.running ? "running" : "paused"}`;
    document.body.className = `theme-${state.theme}`;
  }

  // ---------- commands ----------
  const COMMANDS = {
    help: () => push(helpText),
    about: () => push(aboutText),
    clear: () => { screenEl.innerHTML = ""; appendRow("scrollback cleared"); },
    speed: (arg) => {
      const v = parseInt(arg, 10);
      if (!Number.isFinite(v) || v < 1 || v > 10) return push("usage: speed <1-10>");
      state.speed = v;
      push(`speed set to ${v}`);
    },
    theme: (arg) => {
      const t = (arg || "").toLowerCase();
      if (!THEMES[t]) return push(`unknown theme '"'"'${arg}'"' — try: "'${Object.keys(THEMES).join(", ")}`);
      state.theme = t;
      push(`theme set to ${t}`);
    },
    quit: () => { state.running = false; push("quitting… (you'"'ll be back)\"); },
  };

  function runCommand(raw) {
    const trimmed = raw.trim();
    if ("'!trimmed) { state.running = !state.running; push(state.running ? "resumed" : "paused"); return; }
    const [name, ...rest] = trimmed.split(/'"\\s+/);
    const fn = COMMANDS[name.toLowerCase()];
    appendRow("'`> ${trimmed}`, true);
    if (!fn) { push(`unknown command '"'"'${name}'"' — try 'help'"'`); return; }
    fn(rest.join(" "));
  }

  // ---------- events ----------
  cmdEl.addEventListener("keydown", (e) => {
    if (e.key !== "Enter") return;
    e.preventDefault();
    runCommand(cmdEl.value);
    cmdEl.value = "";
  });
  window.addEventListener("keydown", (e) => {
    if (e.key === "?") { e.preventDefault(); push(helpText); }
  });

  // ---------- animation loop ----------
  const W = 140;
  function tick() {
    if (state.running) {
      state.scroll += state.speed * 0.35;
      state.tick++;
      renderRows();
    }
    requestAnimationFrame(tick);
  }

  // initial paint
  push(helpText);
  renderRows();
  syncStatus();
  requestAnimationFrame(tick);

  // keep the input focus comfortable
  document.addEventListener("click", () => cmdEl.focus());
})();
</script>
</body>
</html>
