  function runCommand(raw) {
    const trimmed = raw.trim();
    if ("'!trimmed) { state.running = !state.running; push(state.running ? "resumed" : "paused"); return; }
    const [name, ...rest] = trimmed.split(/'"\\s+/);
    const fn = COMMANDS[name.toLowerCase()];
    appendRow("'`> ${trimmed}`, true);
    if (!fn) { push(`unknown command '"'"'${name}'"' — try 'help'"'`); return; }
    fn(rest.join(" "));
  }

  // ---------- events ----------
  cmdEl.addEventListener("keydown", (e) => {
    if (e.key !== "Enter") return;
    e.preventDefault();
    runCommand(cmdEl.value);
    cmdEl.value = "";
  });
  window.addEventListener("keydown", (e) => {
    if (e.key === "?") { e.preventDefault(); push(helpText); }
  });

  // ---------- animation loop ----------
  const W = 140;
  function tick() {
    if (state.running) {
      state.scroll += state.speed * 0.35;
      state.tick++;
      renderRows();
    }
    requestAnimationFrame(tick);
  }

  // initial paint
  push(helpText);
  renderRows();
  syncStatus();
  requestAnimationFrame(tick);

  // keep the input focus comfortable
  document.addEventListener("click", () => cmdEl.focus());
})();
