  // ---------- ASCII scene generation ----------
  const rand = (a, b) => a + Math.random() * (b - a);
  const mod = (n, m) => ((n % m) + m) % m;

  const STAR = \" .·*+o\";
  const HILL_DARK = [\"▓\", \"▒\", \"░\"];
  const HILL_LIGHT = [\"█\", \"▓\", \"▒\"];
  const BUSHES = [\"♣\", \"⚘\", \"✿\", \"٭\", \"⌂\"];
  const ROCKS  = [\"#\", \"&\", \"%\", \"@\"];
  const CLOUD  = [\"·\", \""'`", "´", "~", "_"];

  const W = 140;

  function makeStars() {
    const stars = [];
    for (let i = 0; i < 70; i++) stars.push({ x: rand(0, W), y: int(rand(0, 6)), c: pick(STAR) });
    return stars;
  }
  function makeHills() {
    const hills = [];
    for (let i = 0; i < 9; i++) hills.push({ x: rand(0, W), w: int(rand(10, 26)), h: int(rand(3, 7)) });
    return hills;
  }
  function makeProps() {
    const props = [];
    for (let i = 0; i < 16; i++) props.push({ x: rand(0, W), kind: Math.random() < 0.65 ? "bush" : "rock" });
    return props;
  }

  const stars = makeStars();
  const hills = makeHills();
  const props = makeProps();

  // Returns Map: y -> array of {x, ch} for the given world offset.
  function compose(offset) {
    const buckets = new Map();
    const pushX = (y, x, ch) => {
      x = mod(Math.round(x), W);
      if (!buckets.has(y)) buckets.set(y, []);
      buckets.get(y).push({ x, ch });
    };
    for (const s of stars) pushX(s.y, s.x - offset * 0.25, s.c);
    for (const h of hills) {
      for (let i = 0; i < h.w; i++) {
        const y = 5 - Math.round(h.h * Math.sin((i / h.w) * Math.PI));
        pushX(y, h.x + i - offset * 0.5, y > 3 ? pick(HILL_DARK) : pick(HILL_LIGHT));
      }
    }
    for (const p of props) {
      const y = 4 + (p.kind === "rock" ? 1 : 0);
      pushX(y, p.x - offset * 1.0, p.kind === "rock" ? pick(ROCKS) : pick(BUSHES));
    }
    return buckets;
  }

  function renderRows() {
    const offset = state.scroll;
    const rows = [];
    for (let i = 0; i < state.rows; i++) rows.push(Array(W).fill(" "));

    const g = Math.floor(state.rows * 0.82);
    for (let x = 0; x < W; x++) rows[g][x] = "─";

    const cells = compose(offset);
    for (const [y, list] of cells) {
      const row = rows[y];
      for (const it of list) if (row[it.x] === " ") row[it.x] = it.ch;
    }

    // occasional cloud drift in the upper band
    for (let y = 0; y < Math.min(6, g); y++) {
      if (Math.random() < 0.02) {
        rows[y][int(rand(0, W))] = pick(CLOUD);
      }
    }

    const moonY = Math.floor(g * 0.25), moonX = W - 26;
    if (moonY < g) rows[moonY][moonX] = "☾";

    screenEl.textContent = rows.map((r) => r.join("")).join("'"\\n\");
  }
