function compose(offset) {
  const buckets = new Map();
  const pushX = (y, x, ch) => {
    x = mod(Math.round(x), W);
    if (!buckets.has(y)) buckets.set(y, []);
    buckets.get(y).push({ x, ch });
  };
  for (const s of stars) pushX(s.y, s.x - offset * 0.25, s.c);
  for (const h of hills) {
    for (let i = 0; i < h.w; i++) {
      const y = 5 - Math.round(h.h * Math.sin((i / h.w) * Math.PI));
      pushX(y, h.x + i - offset * 0.5, y > 3 ? pick(HILL_DARK) : pick(HILL_LIGHT));
    }
  }
  for (const p of props) {
    const y = 4 + (p.kind === "rock" ? 1 : 0);
    pushX(y, p.x - offset * 1.0, p.kind === "rock" ? pick(ROCKS) : pick(BUSHES));
  }
  return buckets;

